<?php
require_once __DIR__.'/../includes/functions.php';admin_only();$pageTitle='Student applications';$status=trim($_GET['status']??'');$iid=filter_input(INPUT_GET,'internship',FILTER_VALIDATE_INT);$sql="SELECT a.id,a.applied_at,a.status,s.name,s.email,s.college,s.course,i.title,i.company FROM applications a JOIN students s ON s.id=a.student_id JOIN internships i ON i.id=a.internship_id WHERE 1=1";$p=[];if(in_array($status,['Pending','Under Review','Shortlisted','Accepted','Rejected'],true)){$sql.=" AND a.status=?";$p[]=$status;}if($iid){$sql.=" AND i.id=?";$p[]=$iid;}$sql.=" ORDER BY a.applied_at DESC";$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();$internships=$pdo->query("SELECT id,title FROM internships ORDER BY title")->fetchAll();include __DIR__.'/../includes/header.php'; ?>
<h1 class="page-title">Student applications</h1><form class="filter-panel row g-2 mb-3"><div class="col-md-5"><select class="form-select" name="internship"><option value="">All internships</option><?php foreach($internships as $in): ?><option value="<?= (int)$in['id'] ?>" <?= $iid===$in['id']?'selected':'' ?>><?= e($in['title']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Pending','Under Review','Shortlisted','Accepted','Rejected'] as $v): ?><option <?= $status===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><div class="col-auto"><button class="btn btn-primary">Filter</button></div></form>
<div class="table-responsive panel"><table class="table align-middle"><thead><tr><th>Student</th><th>Internship</th><th>Applied</th><th>Status</th><th>Update status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><br><small><?= e($r['email']) ?></small><br><small><?= e($r['college']) ?> · <?= e($r['course']) ?></small></td><td><?= e($r['title']) ?><br><small><?= e($r['company']) ?></small></td><td><?= e(date('d M Y',strtotime($r['applied_at']))) ?></td><td><?= e($r['status']) ?></td><td><form method="post" action="update-status.php" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select class="form-select form-select-sm" name="status"><?php foreach(['Pending','Under Review','Shortlisted','Accepted','Rejected'] as $v): ?><option <?= $r['status']===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="text-center">No applications found.</td></tr><?php endif; ?></tbody></table></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
